// SEM IA: compara o dia pedido (ou o mais recente) com os 5 resumos anteriores, e a semana com a anterior.
// Não cita ex-colaboradores nem cobra o CEO. Obs.: o resumo de segunda junta sexta a domingo.
// 28/10: o fechamento do dia chega depois do corte (18h), então "enviou relatório?" olha o DIA ÚTIL ANTERIOR
// (as métricas já contam o relatório no dia a que ele se refere).
const EX_COLABORADORES = ['Redacted', 'Redacted', 'Redacted']; // mesma lista da trava de privacidade
const fora = p => EX_COLABORADORES.some(n => new RegExp('(^|\\s)' + n + '(\\s|$)', 'i').test(p)) || /Jos[ée] Redacted/i.test(p);
const rows = $input.all().map(i => i.json).filter(r => r.dia && r.pessoa && !fora(r.pessoa));
if (!rows.length) return [{ json: { resultado: 'Ainda não há métricas registradas.' } }];
const dias = [...new Set(rows.map(r => r.dia))].sort();
const pedido = String($('Pedido do agente').first().json.data || '').match(/\d{4}-\d{2}-\d{2}/);
const hoje = pedido && dias.includes(pedido[0]) ? pedido[0] : dias[dias.length - 1];
const antes = dias.filter(d => d < hoje);
const ult5 = antes.slice(-5), prev5 = antes.slice(-10, -5);
const diaFech = antes[antes.length - 1];
const baseFech = antes.slice(-6, -1);
const br = d => d ? d.slice(8, 10) + '/' + d.slice(5, 7) : '';
const soma = (f, campo) => rows.filter(f).reduce((s, r) => s + Number(r[campo] || 0), 0);
const linhas = [];
// Pessoas
const pessoas = [...new Set(rows.map(r => r.pessoa))];
const alertas = [], destaques = [];
for (const p of pessoas) {
  const msgHoje = soma(r => r.pessoa === p && r.dia === hoje, 'mensagens');
  const relHoje = soma(r => r.pessoa === p && r.dia === hoje, 'relatorios');
  if (diaFech) {
    const relFech = soma(r => r.pessoa === p && r.dia === diaFech, 'relatorios');
    const diasComRel = baseFech.filter(d => soma(r => r.pessoa === p && r.dia === d, 'relatorios') > 0).length;
    if (diasComRel >= 3 && relFech === 0) alertas.push(p + ': costuma enviar relatório/fechamento (' + diasComRel + ' dos ' + baseFech.length + ' dias anteriores) e NÃO enviou o de ' + br(diaFech) + '.');
    else if (diasComRel >= 4 && relFech > 0) destaques.push(p + ': fechamento de ' + br(diaFech) + ' enviado (' + (diasComRel + 1) + ' de ' + (baseFech.length + 1) + ' dias).');
  }
  const mediaMsg = ult5.length ? soma(r => r.pessoa === p && ult5.includes(r.dia), 'mensagens') / ult5.length : 0;
  if (mediaMsg >= 3 && msgHoje === 0 && relHoje === 0) alertas.push(p + ': sem mensagens hoje (média ' + mediaMsg.toFixed(1).replace('.', ',') + '/dia).');
}
// Espaços: hoje x média, semana x semana anterior
const espacos = [...new Set(rows.map(r => r.espaco))];
const esp = [];
for (const e of espacos) {
  const h = soma(r => r.espaco === e && r.dia === hoje, 'mensagens');
  const m = ult5.length ? soma(r => r.espaco === e && ult5.includes(r.dia), 'mensagens') / ult5.length : 0;
  const s1 = soma(r => r.espaco === e && (ult5.includes(r.dia) || r.dia === hoje), 'mensagens');
  const s0 = soma(r => r.espaco === e && prev5.includes(r.dia), 'mensagens');
  if (m >= 3 && (h <= m * 0.5 || h >= m * 1.5)) esp.push(e + ': ' + h + ' mensagens hoje × média ' + m.toFixed(1).replace('.', ',') + (h < m ? ' (queda)' : ' (alta)') + '.');
  if (prev5.length >= 3 && s0 >= 10 && (s1 <= s0 * 0.6 || s1 >= s0 * 1.4)) esp.push(e + ': semana com ' + s1 + ' mensagens × ' + s0 + ' na semana anterior.');
}
linhas.push('TENDÊNCIA (dia ' + hoje + ' comparado com ' + ult5.length + ' resumos anteriores; métricas sem IA, só mensagens em espaços). Fechamentos: checado o de ' + br(diaFech) + ' (o de hoje chega depois do corte das 18h e NÃO deve ser cobrado):');
linhas.push(alertas.length ? 'ATENÇÃO:\n- ' + alertas.slice(0, 8).join('\n- ') : 'ATENÇÃO: nada fora do padrão.');
if (destaques.length) linhas.push('CONSTÂNCIA:\n- ' + destaques.slice(0, 6).join('\n- '));
if (esp.length) linhas.push('ESPAÇOS:\n- ' + esp.slice(0, 6).join('\n- '));
linhas.push('Use como sinal, não como prova: pode ter sido enviado por outro canal. Confirme no resumo do dia antes de cobrar.');
return [{ json: { resultado: linhas.join('\n').slice(0, 3000) } }];
